-- Tags on companies, from a catalog of their own (separate from the contact
-- tags). The new view column comes last, which lets the view be replaced in
-- place.

create table "public"."company_tags" (
    "id" bigint generated by default as identity not null,
    "name" text not null,
    "color" text not null
);

alter table "public"."company_tags" enable row level security;

alter table "public"."company_tags" add constraint "company_tags_pkey" primary key ("id");

alter table "public"."companies" add column "tags" bigint[];

grant all on table "public"."company_tags" to "anon";
grant all on table "public"."company_tags" to "authenticated";
grant all on table "public"."company_tags" to "service_role";

create policy "Enable read access for authenticated users" on "public"."company_tags" as permissive for select to authenticated using (true);
create policy "Enable insert for authenticated users only" on "public"."company_tags" as permissive for insert to authenticated with check (true);
create policy "Enable update for authenticated users only" on "public"."company_tags" as permissive for update to authenticated using (true);
create policy "Enable delete for authenticated users only" on "public"."company_tags" as permissive for delete to authenticated using (true);

create or replace view "public"."companies_summary" with (security_invoker = on) as
select
    c.id,
    c.created_at,
    c.name,
    c.sector,
    c.size,
    c.linkedin_url,
    c.website,
    c.phone_number,
    c.address,
    c.zipcode,
    c.city,
    c.state_abbr,
    c.sales_id,
    c.context_links,
    c.country,
    c.description,
    c.revenue,
    c.tax_identifier,
    c.logo,
    c.nb_sites,
    c.nb_trainings_delivered,
    c.training_date,
    c.quote_approved,
    c.service_invoiced,
    count(distinct d.id) as nb_deals,
    count(distinct co.id) as nb_contacts,
    c.tags
from public.companies c
    left join public.deals d on c.id = d.company_id
    left join public.contacts co on c.id = co.company_id
group by c.id;
